const status=(j:Job)=>j.status==='Completed'?'Completed':j.status==='Deleted'?'In Trash':j.status==='Cancelled'?'Archived':j.status==='On Hold'?'On hold':j.confirmed_at?stage(j):'Awaiting confirmation';
