// Calendar order first, manual urgency breaks ties only. No stored priorities change.
const sort=(a:Job,b:Job)=>a.due_date.localeCompare(b.due_date)||Number(b.priority==='Urgent')-Number(a.priority==='Urgent')||a.id-b.id;
const productionSort=(a:Job,b:Job)=>Number(a.production_status==='Ready to Collect')-Number(b.production_status==='Ready to Collect')||sort(a,b);


const scheduleMonths=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
function scheduleRange(job:Job){
 const [od,om,oy]=date(job.date_in).split('/');
 const [dd,dm,dy]=date(job.due_date).split('/');
 return `${Number(od)} ${scheduleMonths[Number(om)-1]}${oy!==dy?' '+oy:''} – ${Number(dd)} ${scheduleMonths[Number(dm)-1]} ${dy}`;
}
type ScheduleMode='designer'|'production'|'trash';
function deadlineReminder(job:Job,mode:ScheduleMode){
 const days=due(job);
 const live=mode==='production'?!['Deleted','Cancelled'].includes(job.status)&&job.production_status!=='Ready to Collect':mode==='designer'&&active(job);
 const tone=!live?'inactive':days<0?'late':days===0?'today':days===1?'tomorrow':days===2?'two-days':days===3?'three-days':'normal';
 const detail=!live?'':days<0?`${-days} ${days===-1?'day':'days'} overdue`:days===0?'Due today':days===1?'Due tomorrow':`Due in ${days} days`;
 return {live,tone,detail};
}
function JobDeadlineReminder({job,mode='designer'}:{job:Job;mode?:ScheduleMode}){
 const {live,tone,detail}=deadlineReminder(job,mode);
 if(!live)return null;
 return <span className={'ticket-reminder reminder-'+tone}><Icon name="bell"/><span className="schedule-detail">{detail}</span></span>;
}
function JobSchedule({job,mode='designer'}:{job:Job;mode?:ScheduleMode}){
 const [dd,dm]=date(job.due_date).split('/');
 const dueMonth=scheduleMonths[Number(dm)-1];
 const {live,tone}=deadlineReminder(job,mode);
 const fullDates=`Date ordered: ${date(job.date_in)}; Due date: ${date(job.due_date)}`;
 return <div className={'job-schedule schedule-'+tone} title={fullDates}>
  <span className="schedule-calendar" aria-label={'Due date '+date(job.due_date)}><span className="schedule-month">{dueMonth}</span><strong>{Number(dd)}</strong></span>
  {!live&&<span className="schedule-detail">{mode==='trash'?'Original due date':mode==='production'?'Ready to collect':status(job)}</span>}
 </div>;
}

function JobWorkspaceSummary({job}:{job:Job}){
 const mode:ScheduleMode=job.status==='Deleted'?'trash':job.production_status?'production':'designer';
 const {live,tone,detail}=deadlineReminder(job,mode);
 const reached=job.status==='Completed'?workflow.length:job.confirmed_at?Math.max(0,workflow.indexOf(stage(job))+1):0;
 const fullDate=date(job.due_date),[dd,mm]=fullDate.split('/');
 return <div className="job-dates apple-job-summary">
  <div className={'apple-summary-card apple-deadline-card schedule-'+tone}>
   <Icon name="calendar"/>
   <span className="apple-summary-label">Delivery due</span>
   <strong className="apple-summary-value">{Number(dd)} {scheduleMonths[Number(mm)-1]}</strong>
   <span className="apple-full-date">{fullDate}</span>
   {live?<span className="apple-summary-reminder"><Icon name="bell"/>{detail}</span>:<span className="apple-summary-reminder">{mode==='production'?'Ready to collect':status(job)}</span>}
   <span className="apple-order-date">Ordered {date(job.date_in)}</span>
  </div>
  <div className="apple-summary-card apple-progress-card">
   <svg viewBox="0 0 48 48" className="apple-progress-ring" aria-hidden="true"><circle className="apple-ring-track" cx="24" cy="24" r="19"/><circle className="apple-ring-value" cx="24" cy="24" r="19" strokeDasharray={String(2*Math.PI*19*reached/workflow.length)+' '+String(2*Math.PI*19)} transform="rotate(-90 24 24)"/>{reached===workflow.length&&<path d="m16 24 5 5 11-12" className="apple-ring-check"/>}</svg>
   <span className="apple-summary-label">File preparation</span>
   <strong className="apple-summary-value apple-progress-value"><span>{reached}</span><small> / {workflow.length}</small></strong>
   <span className="apple-full-date">Stages reached</span>
   <div className="apple-stage-segments" aria-hidden="true">{workflow.map((w,i)=><i key={w} className={i<reached?'reached':''}/>)}</div>
   <span className="apple-stage-caption">{status(job)}</span>
  </div>
 </div>;
}

